      charts.push(chart)
      return chart
    } },
  })
  t.after(() => { mounted.unmount(); restore.forEach(fn => fn()) })
  for (const name of ['income', 'shouKuan', 'zhiChu', 'trend']) mounted.state[`${name}ChartEl`].value = { name }
  return { ...mounted, charts, listeners, flush: () => frames.splice(0).forEach(fn => fn()) }
}

